import { describe, it, expect } from 'vitest'
import request from 'supertest'
import app from '../../src/app'

describe('HTTP status codes for creation endpoints', () => {

  it('returns 201 for POST /upload/perfil (file creation)', async () => {
    const fakeImage = Buffer.from(
      '',
      'hex',
    )
    const res = await request(app)
      .post('/upload/perfil')
      .attach('foto_perfil', fakeImage, {
        filename: 'test.jpg',
        contentType: 'image/jpeg',
      })

    expect(res.status).toBe(201)
    expect(res.body).toHaveProperty('foto_perfil')
  })

  it('returns 201 for POST /upload/registro (file creation)', async () => {
    const fakeImage = Buffer.from(
      '',
      'hex',
    )
    const res = await request(app)
      .post('/upload/registro')
      .attach('foto_credencial', fakeImage, {
        filename: 'credencial.jpg',
        contentType: 'image/jpeg',
      })
      .attach('foto_perfil', fakeImage, {
        filename: 'perfil.jpg',
        contentType: 'image/jpeg',
      })

    expect(res.status).toBe(201)
  })
})

describe('HTTP status codes for deletion endpoints (unauthenticated → 401)', () => {
  it('returns 401 (not 204) for notificaciones.eliminar without auth', async () => {
    const res = await request(app)
      .post('/rpc/notificaciones/eliminar')
      .send({ id: 1 })
      .set('Content-Type', 'application/json')

    // Without token, auth middleware rejects with 401 before reaching the handler
    expect(res.status).toBe(401)
  })

  it('returns 401 (not 204) for chat.eliminarHistorial without auth', async () => {
    const res = await request(app)
      .post('/rpc/chat/eliminarHistorial')
      .send({ idViaje: 1 })
      .set('Content-Type', 'application/json')

    expect(res.status).toBe(401)
  })
})
